            if (pdListN >= pdList.Length)
            {
                int[] g = new int[pdList.Length * 2];
                System.Array.Copy(pdList, g, pdListN);
                pdList = g;
            }
            pdList[pdListN++] = d; pdCount[k]++; pdTotal[k] += defSlotWeight[d];
