            if (pass == 0 && roll && seated == 0 && firstEmpty >= 0 && (emitFlags[host] & EF_BOOTH) == 0)
            {
                int seat = chosen >= 0 ? chosen : TwinIn(room, PickDef(slotAccept[firstEmpty], slotSize[firstEmpty], theme, rng));
                if (seat >= 0 && EmitInSlot(host, firstEmpty, seat, 0, rng) >= 0)
                {
