    // put def cd into slot sl of the host. Returns the emit index, or -1 if an ADJACENT slot is blocked.
    int EmitInSlot(int host, int sl, int cd, int flags, uint[] rng)
    {
        int type = slotType[sl];
        int room = emitRoom[host];
        int lx = slotX[sl], lz = slotZ[sl];
        if (type == GenData.S_ADJACENT)
        {
            // pulled out 0 to 25 cm away from the host
            int pull = RngBetween(rng, 0, 250);
            int yawJ = Jitter(rng, 12);
            int len = ISqrt(lx * lx + lz * lz);
            if (len > 0) { lx += lx * pull / len; lz += lz * pull / len; }
            // the cell is the one the chair's centre really lands in (the host has a few cm and degrees of jitter)
            int wx, wz;
            Local(host, lx, lz, out wx, out wz);
            int cx = FloorDiv(wx, GenData.INNER_MM), cz = FloorDiv(wz, GenData.INNER_MM);
            if (cx < 0 || cz < 0 || cx >= IW || cz >= IH) return -1;
            int ci = cz * IW + cx;
            int t = tags[ci];
            if ((t & GenData.T_FLOOR) == 0 || (t & (GenData.T_BLOCKED | GenData.T_NO_SPAWN | GenData.T_DOOR_CLEAR)) != 0) return -1;
            if (innerRoom[ci] != room || (occ[ci] != 0 && occ[ci] != host + 1) || (reserve[ci] != 0 && reserve[ci] != host + 1))
            {
                return -1;
            }
            // the chair's whole outline keeps clear of walls and fences, and of what already stands around (G31)
            int chx, chz, cyaw = emitYaw[host] + slotYaw[sl] + yawJ;
            FullHalf(cd, cyaw, out chx, out chz);
            if (!ExtentClear(cd, wx, wz, cyaw, host))
            {
                return -1;
            }
            int sx0 = FloorDiv(wx - chx + SOLID_TOL, GenData.INNER_MM), sx1 = FloorDiv(wx + chx - SOLID_TOL - 1, GenData.INNER_MM);
            int sz0 = FloorDiv(wz - chz + SOLID_TOL, GenData.INNER_MM), sz1 = FloorDiv(wz + chz - SOLID_TOL - 1, GenData.INNER_MM);
            if (sx1 < sx0) { sx0 = cx; sx1 = cx; }
            if (sz1 < sz0) { sz0 = cz; sz1 = cz; }
            for (int z = sz0; z <= sz1; z++)
                for (int x = sx0; x <= sx1; x++)
                {
                    if (x < 0 || z < 0 || x >= IW || z >= IH) return -1;
                    int i2 = z * IW + x, o = occ[i2];
                    if (o != 0 && o != host + 1 && emitParent[o - 1] != host)
                    {
                        return -1;
                    }
                    // a seat keeps off the walkway between doors and off a doorway's clear floor
                    if ((tags[i2] & (GenData.T_DOOR_CLEAR | GenData.T_PATH)) != 0 || innerRoom[i2] != room)
                    {
                        return -1;
                    }
                }
            if (!NeighboursClear(cd, wx, wz, cyaw, sx0, sz0, sx1 - sx0 + 1, sz1 - sz0 + 1, host))
            {
                return -1;
            }
            int e = Emit(cd, wx, 0, wz, cyaw, host, room, flags | EF_ADJACENT);
            if (e < 0) return -1;
            emitSlot[e] = sl;
            // the seat holds every cell its outline covers, so nothing is placed into it later
            emitRX[e] = sx0; emitRZ[e] = sz0; emitRW[e] = sx1 - sx0 + 1; emitRD[e] = sz1 - sz0 + 1; emitRot[e] = (emitRot[host] + slotYaw[sl] / 90) & 3;
            for (int z = sz0; z <= sz1; z++)
                for (int x = sx0; x <= sx1; x++)
                    if (occ[z * IW + x] == 0) occ[z * IW + x] = e + 1;
            Account(e, 1);
            return e;
        }
        else
        {
            int f = type == GenData.S_ON_TOP ? EF_ON_TOP : (type == GenData.S_INSIDE ? EF_INSIDE : EF_UNDER);
            int j = type == GenData.S_UNDER ? 0 : Min(defJitPos[cd] * 10, 30);
            int jx = Jitter(rng, j), jz = Jitter(rng, j);
            bool upright = (defTags[cd] & (GenData.I_SETTING | GenData.I_SCREEN | GenData.I_LAMP)) != 0;
            int yawJ = type == GenData.S_UNDER ? 0 : Jitter(rng, upright ? 6 : 25);
            int wx, wz;
            Local(host, lx + jx, lz + jz, out wx, out wz);
            // nothing on or under furniture reaches through the wall behind it (G31): straighten it, or leave the place empty
            int ihx, ihz, iyaw = emitYaw[host] + slotYaw[sl] + yawJ;
            bool outd = (tags[FloorDiv(emitZ[host], GenData.INNER_MM) * IW + FloorDiv(emitX[host], GenData.INNER_MM)] & GenData.T_OUTDOOR) != 0;
            FullHalf(cd, iyaw, out ihx, out ihz);
            if (!WallsClear(wx - ihx, wz - ihz, wx + ihx, wz + ihz, outd))
            {
                iyaw = emitYaw[host] + slotYaw[sl];
                Local(host, lx, lz, out wx, out wz);
                FullHalf(cd, iyaw, out ihx, out ihz);
                if (!WallsClear(wx - ihx, wz - ihz, wx + ihx, wz + ihz, outd)) return -1;
            }
            int e = Emit(cd, wx, emitY[host] + slotY[sl], wz, iyaw, host, room, flags | f);
            if (e < 0) return -1;
            emitSlot[e] = sl;
            emitRX[e] = FloorDiv(wx, GenData.INNER_MM); emitRZ[e] = FloorDiv(wz, GenData.INNER_MM); emitRW[e] = 0; emitRD[e] = 0;
            emitRot[e] = emitRot[host];
            Account(e, 1);
            return e;
        }
    }

    int FloorDiv(int a, int b) { int q = a / b; if ((a % b != 0) && ((a < 0) != (b < 0))) q--; return q; }

    int ISqrt(int v)
    {
        if (v <= 0) return 0;
        int r = 0;
        for (int bit = 1 << 15; bit > 0; bit >>= 1)
        {
            int t = r | bit;
            if ((long)t * t <= v) r = t;
        }
        return r;
    }

    // =====================================================================================================
    // Wrong-category spawns (04 section 4.3.5; Q13, Q14, D10)
    // =====================================================================================================
    bool[] nativeIn;   // [def * GenData.MAX_TABLES + table]: the def is in that room type's spawn table
    int[] nativeZones; // per def: bit per zone

    void BuildNative()
    {
        if (nativeIn != null) return;
        nativeIn = new bool[nDefs * GenData.MAX_TABLES];
        nativeZones = new int[nDefs];
        for (int t = 0; t < nTables; t++)
        {
            int es = tableEntryStart[t], n = tableEntryCount[t];
            for (int e = es; e < es + n; e++)
            {
                int g = entryGrp[e];
                int ms = g < 0 ? 0 : grpMemberStart[g], mc = g < 0 ? 1 : grpMemberCount[g];
                for (int m = 0; m < mc; m++)
                {
                    int d = g < 0 ? entryDef[e] : grpMemberDef[ms + m];
                    nativeIn[d * GenData.MAX_TABLES + t] = true;
                    nativeZones[d] |= 1 << tableZone[t];
                }
            }
        }
    }

    // is this def in the spawn table of the room's type? (used by bots to pick plausible places)
    public bool IsNativeRoom(int def, int room)
    {
        BuildNative();
        int table = FindTable(roomZone[room], roomType[room]);
        return table >= 0 && nativeIn[def * GenData.MAX_TABLES + table];
    }

    int LeakWeight(int d, int table, int zone, bool outdoor, bool comedic)
    {
        int w = defLeakWeight[d];
        if (w == 0) return 0;
        if (!Has(d, outdoor ? GenData.FL_LEAK_OUT : GenData.FL_LEAK_IN)) return 0;
        if (table >= 0 && nativeIn[d * GenData.MAX_TABLES + table]) return 0;                       // native here: not a leak
        if (comedic)
        {
            if (defAbsurd[d] < 2) return 0;
            if ((nativeZones[d] & (1 << zone)) != 0) return 0;                       // comedic leaks come from another zone
        }
        else if (defAbsurd[d] > 1) return 0;
        return w;
    }

